sys_script.script:
(function executeRule(current, previous) {
    if (current.operation() != 'insert' && !current.status.changes()) {
        return;
    }
    var sync = new x_2056099_indust_0.OrderToProductionSync();
    sync.syncFromProductionOrder(current);
    if (current.operation() == 'update' && current.status.changesTo('completed')) {
        sync.postFinishedGoods(current);
    }
})(current, previous);
